const nodemailer = require('nodemailer');
if (state.sendEmail) {
  const transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: parseInt(process.env.SMTP_PORT),
    secure: true,
    auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS }
  });
  const mailOptions = {
    from: process.env.SMTP_USER,
    to: state.email,
    subject: `Your Quote from TopherAI`,
    text: `Hello ${state.name},\n\nHere’s your personalized quote for the ${state.plan} plan: ${state.quote}.\nThis quote is valid for 7 days.\n\nBusiness: ${state.business}\nWebsite: ${state.website}\nPhone: ${state.phone}\n\nIf you’d like to move forward, visit https://www.topherai.com/#pricing.\n\nThank you,\nThe TopherAI Team`
  };
  await transporter.sendMail(mailOptions);
}
return state;
